import sys,os
sys.path.append(os.path.abspath(os.path.dirname(__file__) + '/' + '..'))

from typing import Dict, List, TypedDict, Optional
from functools import reduce
import operator

class RoadMapNode(TypedDict):
    id: str
    name: str
    label: str
    score: float
    nodeLevel: int  # Added nodeLevel field

RoadMapEdge = TypedDict('RoadMapEdge', {
    'from': str,
    'to': str,
    'weight': float,
    'type': str,
    'relation': str
})

class PathElement(TypedDict):
    node: RoadMapNode
    edge: Optional[RoadMapEdge]

class RoadMapEntry(TypedDict):
    knowledgeDbId: str
    similarity: float
    startNode: Dict[str, str]
    endNode: Dict[str, str]
    path: List[PathElement]

def geometric_mean(numbers: List[float]) -> float:
    if not numbers:
        return 0.0
    product = reduce(operator.mul, numbers, 1.0)
    return product ** (1.0 / len(numbers))

def _FUNC_SCORE(sim1: float, sim2: float) -> float:
    return round(max(sim1, sim2) * 0.95 + min(sim1, sim2) * 0.05, 5)

def calculate_similarity(scores: List[float]) -> float:
    valid_scores = [s for s in scores if s > 0]
    if not valid_scores:
        return 0.0
    geo_mean = geometric_mean(valid_scores)
    arith_mean = sum(valid_scores) / len(valid_scores)
    return _FUNC_SCORE(geo_mean, arith_mean)

class PathTransformer:
    def __init__(self, knowledge_db_id: str = "11"):
        self.knowledge_db_id = knowledge_db_id

    def _build_node_dict(self, nodes: List[Dict]) -> Dict[str, Dict]:
        return {node["nodeId"]: node for node in nodes}  # Match screenshot's nodeId

    def _get_path_scores(self, nodes: List[Dict], edges: List[Dict]) -> List[float]:
        return [node.get("score", 0) for node in nodes if node.get("score", 0) > 0]

    def _build_start_end_nodes(self, nodes: List[Dict]) -> Dict[str, Dict[str, str]]:
        if not nodes:
            raise ValueError("Empty node list")

        def level_sort_key(node):
            raw_level = node.get("nodeLevel", 0)
            # Convert -1 to max_level for sorting
            return (float('inf') if raw_level == -1 else raw_level, -node.get("score", 0))

        # Start node: lowest level (smallest number) with highest score
        start_node = min(nodes, key=level_sort_key)

        # End node: highest level (including -1) with highest score
        end_node = max(nodes, key=lambda x: (
            -1 if x.get("nodeLevel", 0) == -1 else -x.get("nodeLevel", 0), 
            -x.get("score", 0)
        ))

        return {
            "start": self._format_node_info(start_node),
            "end": self._format_node_info(end_node)
        }

    def _format_node_info(self, node: Dict) -> Dict[str, str]:
        return {
            "nodeUid": node["nodeId"],
            "nodeName": node.get("nodeName", ""),
            "nodelabel": node.get("nodeLabelName", ""),
            "nodeLevel": str(node.get("nodeLevel", 0))  # Added level info
        }

    def _build_path_elements(self, edges: List[Dict], node_map: Dict[str, Dict]) -> List[PathElement]:
        path_elements = []
        for edge in edges:
            from_node = node_map.get(edge["fromNodeId"])
            to_node = node_map.get(edge["toNodeId"])

            if from_node and to_node:
                path_elements.append(PathElement(
                    node=self._build_roadmap_node(from_node),
                    edge=self._build_roadmap_edge(edge)
                ))
                path_elements.append(PathElement(
                    node=self._build_roadmap_node(to_node),
                    edge={}
                ))
        return path_elements

    def _build_roadmap_node(self, node: Dict) -> RoadMapNode:
        return RoadMapNode(
            id=node["nodeId"],
            name=node.get("nodeName", ""),
            label=node.get("nodeLabelName", ""),  # Match screenshot's nodeLabelName
            score=node.get('score', 0.0),
            nodeLevel=node.get('nodeLevel', 0)  # Added nodeLevel
        )

    def _build_roadmap_edge(self, edge: Dict) -> RoadMapEdge:
        return RoadMapEdge(
            from_=edge["fromNodeId"],
            to=edge["toNodeId"],
            weight=edge.get("edgeWeight", 1.0),
            type=edge.get("type", "directed"),
            relation=edge.get("relationZh", "")
        )

    def transform(self, merged_paths: List[Dict]) -> Dict[str, List[RoadMapEntry]]:
        road_map_list = []
        for path in merged_paths or []:
            nodes = path.get("nodes", [])
            edges = path.get("edges", [])

            if nodes and edges:
                try:
                    node_map = self._build_node_dict(nodes)
                    scores = self._get_path_scores(nodes, edges)
                    similarity = calculate_similarity(scores)
                    endpoints = self._build_start_end_nodes(nodes)

                    road_map_list.append(RoadMapEntry(
                        knowledgeDbId=self.knowledge_db_id,
                        similarity=round(similarity, 4),
                        startNode=endpoints["start"],
                        endNode=endpoints["end"],
                        path=self._build_path_elements(edges, node_map)
                    ))
                except Exception as e:
                    print(f"Error processing path: {e}")

        return {
            "roadMapList": sorted(
                road_map_list,
                key=lambda x: x['similarity'],
                reverse=True
            )[:4]
        }

